  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('throws for array input', function () {
    assert.throws(function () { ms(['100']); }, /val is not a non-empty string/);
  });
  it('throws for String object input', function () {
    assert.throws(function () { ms(new String('2h')); }, /val is not a non-empty string/);
  });
});

