var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('throws the original error message for invalid input', function () {
    assert.throws(function () { ms(null); }, function (err) {
      return err.message === 'val is not a non-empty string or a valid number. val=null';
    });
  });
});

